  'land.docTitle': "CM Reborn – il CM 01/02 originale nel browser, gratis (beta)",
  'land.nav.features': 'Caratteristiche', 'land.nav.screens': 'Screenshot', 'land.nav.ranking': 'Classifiche', 'land.nav.faq': 'FAQ',
  'land.play': 'Gioca gratis ora', 'land.playShort': 'Gioca ora', 'land.seeScreens': 'Guarda il gioco',
  'land.nost.q1': "Ti ricordi di Tó Madeira e Cherno Samba, i giovani talenti che giuravi sarebbero diventati leggende?",
