  'land.new.tag': "NOVITÀ", 'land.new.title': "Il CM 01/02 originale – ora gratis e online",
  'land.new.text': "Abbiamo convertito il gioco 1:1 nel CM 01/02 originale, con soli extra visivi come gli stemmi dei club. Giocalo gratis nel browser: senza download né installazione.", 'land.check.online': "Gioca online",
  'land.pill': "Gratis · Beta · il CM 01/02 originale", 'land.h1a': "Il CM 01/02 originale.", 'land.h1b': "Ora nel tuo browser.",
  "land.f.pages.title": "Tutti i giocatori sul web",
  "land.f.pages.text": "Circa 17.500 pagine di database: ogni giocatore con attributi, CA/PA, giovani promesse e trasferimenti Bosman – da sfogliare gratis.",
  "land.check.beta": "Beta",
