  // ---------- dynamic press conferences ----------
  'press.q.redCard': '{player} è stato espulso oggi. Ha tradito la squadra?', 'press.q.redCard.2': 'Cosa hai detto a {player} dopo il rosso?',
  'press.q.hero': '{player} oggi è stato straordinario. È il migliore del campionato in questo momento?', 'press.q.hero.2': 'Puoi fare a meno di {player} giocando così?',
  'press.q.newSigning': '{player} è appena arrivato. Quanto in fretta può fare la differenza?', 'press.q.newSigning.2': "{player} è l'uomo giusto per far svoltare questa squadra?",
  'press.q.youngster': '{player} ha solo {age} anni. È pronto per giocare con continuità?', 'press.q.youngster.2': 'Tutti parlano di {player}. Fin dove può arrivare?',
  'press.q.oppStar': 'Come si ferma {player} del {opp}?', 'press.q.oppStar.2': '{player} è in grande forma. Hai un piano speciale per lui?',
  'press.q.titleRace': 'Siete {pos}. Ora siete i favoriti per lo scudetto?', 'press.q.titleRace.2': 'Riuscite a reggere la pressione della corsa al titolo?',
  'press.q.relegation': 'Siete {pos}, in piena lotta salvezza. Come ne uscite?', 'press.q.relegation.2': 'Temi la retrocessione?',
  'press.q.europe': "C'è l'Europa contro il {opp}. Fin dove potete arrivare in {comp}?", 'press.q.europe.2': 'La {comp} è più importante del campionato?',
  'press.q.fans': 'I tifosi sono scontenti. Capisci la loro frustrazione?', 'press.q.fans.2': 'Ci sono stati fischi sugli spalti. Cosa dici ai tifosi?',
  'press.q.rumour': 'Le big inseguono {player}. È in vendita?', 'press.q.rumour.2': 'Riuscirai a trattenere {player} con tutto questo interesse?',
  'press.q.drought': '{player} non segna da {apps} partite. Sei preoccupato?', 'press.q.drought.2': 'Quando inizierà a segnare {player}?',
  'press.q.form.W.2': 'La squadra vola. Qual è il segreto?', 'press.q.form.L.2': 'Ancora una sconfitta. Hai ancora in mano lo spogliatoio?',
  'press.q.result.W.2': 'Vittoria per {score} sul {opp}: la vostra miglior prestazione di quest\'anno?', 'press.q.result.L.2': 'Sconfitta per {score} contro il {opp}. Di chi è la colpa?', 'press.q.result.D.2': '{score} contro il {opp}: due punti persi o uno guadagnato?',
  'press.q.starPlayer.2': '{player} è nella forma della sua vita. Riuscirai a trattenerlo?', 'press.q.slump.2': '{player} delude ancora. Perderà il posto?',
  'press.q.board.2': 'Hai ancora il pieno sostegno della dirigenza?', 'press.q.bigMatch.2': "Tutti parlano della partita contro il {opp}. Che aria si respira nello spogliatoio?",
  'press.q.followPress': 'Non è proprio una risposta. Te lo richiedo: cosa ne pensi?', 'press.q.followPress.2': 'Stai eludendo la domanda. Possiamo avere una risposta chiara?',
  'press.q.followPromise': 'È una promessa? Batterete il {opp}?', 'press.q.followPromise.2': 'Quindi garantisci i tre punti contro il {opp}?',
  'press.q.followPlayer': "Significa che è fuori dall'undici titolare?", 'press.q.followPlayer.2': 'Quindi il suo posto non è più sicuro?',
  'press.tone.promise': 'Sì, vinceremo', 'press.tone.promise.hint': 'Tifosi e squadra lo adorano, ma se perdi lo paghi caro con tifosi, dirigenza e stampa.',
  'press.tone.backtrack': 'Nessuna garanzia', 'press.tone.backtrack.hint': "Sicuro, ma un po' deludente per i tifosi.",
  'press.say.confident': 'Siamo pronti e andiamo a vincere. Questa squadra può battere chiunque.', 'press.say.calm': 'Pensiamo una partita alla volta e ci concentriamo sulla nostra prestazione.',
  'press.say.fiery': 'Che vengano pure! Non temiamo nessuno, e lo sentiranno in campo.', 'press.say.deflect': 'Non entro nel merito adesso.',
  'press.say.backPlayer': 'Ha tutto il mio sostegno. È un giocatore importante per noi.', 'press.say.pressurePlayer': 'Sa benissimo che deve dare di più. Me lo aspetto.',
